    def __init__(
        self,
        df: pl.DataFrame,
        train_period: tuple[str, str],
        valid_period: tuple[str, str],
        test_period: tuple[str, str],
        interval: str = "1d",
        enable_cache: bool = False,
        cache_dir: str | None = None,
    ) -> None:
        super().__init__(
            df=df,
            train_period=train_period,
            valid_period=valid_period,
            test_period=test_period,
            interval=interval,
            enable_cache=enable_cache,
            cache_dir=cache_dir,
        )
        self.set_label("ts_delay(close, -3) / ts_delay(close, -1) - 1")
        self.register_all()

    def register_all(self) -> None:
        self.register_crosssectionlowvolstrength_factors()
        self.register_crosssectionrangeadjustedstrength_factors()
        self.register_crosssectionrelativestrength_factors()
        self.register_crosssectionreturnacceleration_factors()
        self.register_crosssectionturnoversupportedstrength_factors()
        self.register_crosssectionvwapstrength_factors()
        self.register_crosssectionvoladjustedreversal_factors()
        self.register_crosssectionvolumeadjustedstrength_factors()
        self.register_downsidevolatility_factors()
        self.register_gapdownrecovery_factors()
        self.register_gapriskrelease_factors()
        self.register_intradaydrawdownrecovery_factors()
        self.register_klinestructure_factors()
        self.register_liquidity_factors()
        self.register_lowershadowriskrelease_factors()
        self.register_marketimpact_factors()
        self.register_nonlinearbreakdowntrigger_factors()
        self.register_nonlinearbreakouttrigger_factors()
        self.register_nonlinearcompressiontrigger_factors()
        self.register_nonlineargaptrigger_factors()
        self.register_nonlinearturnovercrowdingtrigger_factors()
        self.register_nonlinearvwapdislocationtrigger_factors()
        self.register_nonlinearvolregimetrigger_factors()
        self.register_nonlinearvolumetrigger_factors()
        self.register_panicvolumerelease_factors()
        self.register_pathmemory_factors()
        self.register_pricevolumedivergence_factors()
        self.register_rangeriskrelease_factors()
        self.register_rangevolatility_factors()
        self.register_reversal_factors()
        self.register_riskspikedecay_factors()
        self.register_trend_factors()
        self.register_uppershadowrisk_factors()
        self.register_upsidevolatility_factors()
        self.register_vwapdislocationvolatility_factors()
        self.register_vwapstructure_factors()
        self.register_volatilitycompression_factors()
        self.register_volatilitycompressioncloseposition_factors()
        self.register_volatilityexpansion_factors()
        self.register_volatilityturnovercoupling_factors()
        self.register_diverse_strict_retained_factors()
        self.register_next10_round_factors()
        self.register_base300_corr_retained_factors()
        self.register_raw_counterpart_factors()
        self.register_mega1000_corr_retained_factors()
        self.register_ai4000_corr_retained_factors()

    def register_diverse_strict_retained_factors(self) -> None:
        self._add_specs(self.DIVERSE_STRICT_RETAINED_SPECS)

    def register_next10_round_factors(self) -> None:
        self._add_specs(self.NEXT10_ROUND_SPECS)

    def register_base300_corr_retained_factors(self) -> None:
        self._add_specs(self.BASE300_CORR_RETAINED_SPECS)

